// src/pages/HomePage.js

import React from 'react';

function HomePage() {
    return (
        <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
            <h1>E-Shop Home</h1>
            <p>Welcome to our E-Shop! Use the navigation above to browse our products and categories.</p>
        </div>
    );
}

export default HomePage;
